WITH metrics AS (SELECT *, LAG(shipping_fee, 1) OVER (PARTITION BY store_id ORDER BY shipping_fee ASC, id ASC) AS prev_shipping_fee, LAG(amount, 1) OVER (PARTITION BY status ORDER BY order_date ASC, id ASC) AS prev_amount, NTILE(4) OVER (ORDER BY discount ASC, id ASC) AS discount_bucket FROM orders) SELECT CASE WHEN prev_shipping_fee >= 35 THEN 'PREMIUM' ELSE 'STANDARD' END AS prev_shipping_fee_tier, COUNT(CASE WHEN channel = 'partner' THEN 1 END) AS partner_count, SUM(CASE WHEN channel = 'partner' THEN discount_bucket ELSE 0 END) AS partner_discount_bucket FROM metrics GROUP BY CASE WHEN prev_shipping_fee >= 35 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING COUNT(CASE WHEN channel = 'partner' THEN 1 END) > 1 ORDER BY prev_shipping_fee_tier DESC NULLS LAST
